fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // Empty prefix always matches.
    if p.is_empty() {
        return true;
    }
    // If v is shorter than p, it cannot start with p.
    if v.len() < p.len() {
        return false;
    }

    // Compare corresponding characters up to prefix length.
    for (a, b) in v.iter().take(p.len()).zip(p.iter()) {
        if a != b {
            return false;
        }
    }
    true
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    // Stable filtering: scan left-to-right and push matches in order.
    let mut filtered = Vec::new();
    for s in xs.into_iter() {
        if has_prefix(&s, &p) {
            filtered.push(s);
        }
    }
    filtered
}

